@verbatim
<section class="page au" data-page="signup" data-role="att"><div class="au-shell"><aside class="au-art">
    <img class="for-att" src="https://images.unsplash.com/photo-1711743658461-38c875d37c8e?auto=format&fit=crop&w=1100&q=72" alt="">
    <img class="for-org" loading="lazy" src="https://images.unsplash.com/photo-1778877032995-4ab6cd8fe106?auto=format&fit=crop&w=1100&q=72" alt="">
    <div class="au-shade"></div>
    <div class="au-top"><a class="logo" href="/" aria-label="TICA home"><img src="/assets/tica-ui/img/tica-logo.png" alt="TICA"></a><a class="au-back" href="/"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19 12H5M11 6l-6 6 6 6"/></svg>Back to site</a></div>
    <div class="au-glass for-att"><h2>Never miss a night out</h2><p>Your TICA account gives you:</p><ul><li><i><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="7" y="3" width="10" height="18" rx="2"/><path d="M11 18h2"/></svg></i><span>All your tickets in one place</span></li><li><i><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20s-7-4.500-7-10a4 4 0 0 1 7-2.500A4 4 0 0 1 19 10c0 5.500-7 10-7 10z"/></svg></i><span>Saved events you can come back to</span></li><li><i><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 21s7-6.500 7-11a7 7 0 0 0-14 0c0 4.500 7 11 7 11z"/><circle cx="12" cy="10" r="2.500"/></svg></i><span>Events happening near you</span></li></ul></div>
    <div class="au-glass for-org"><h2>Sell out your next event</h2><p>Your KultureCreator account gives you:</p><ul><li><i><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M13 3L5 14h6l-1 7 8-11h-6z"/></svg></i><span>Your event live in minutes</span></li><li><i><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 8h16v3a2 2 0 0 0 0 3v3H4v-3a2 2 0 0 0 0-3zM14 8v2M14 13v1M14 16v1"/></svg></i><span>Smooth checkout for your guests</span></li><li><i><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 20v-6M12 20V6M19 20v-9"/></svg></i><span>Sales and check-ins as they happen</span></li></ul></div>
  </aside>
  <div class="au-main"><form class="au-card" data-auth="signup" novalidate>
    <h1><span class="for-att">Create your account</span><span class="for-org">Register as an organiser</span></h1><p class="au-sub"><span class="for-att">Buy tickets faster and keep them in one place.</span><span class="for-org">Start selling tickets to your next event.</span></p>
    <div class="au-seg" role="group" aria-label="Account type"><button type="button" data-role="att" aria-pressed="true">I'm attending</button><button type="button" data-role="org" aria-pressed="false">I'm organising</button></div><button class="au-g" type="button" data-demo><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="#4285F4" d="M22 12.200c0-.7-.1-1.400-.2-2H12v3.900h5.600a4.800 4.800 0 0 1-2.100 3.100v2.600h3.400c2-1.800 3.100-4.500 3.100-7.600z"/><path fill="#34A853" d="M12 22.500c2.800 0 5.200-.9 6.900-2.500l-3.400-2.600c-.9.600-2.100 1-3.500 1-2.700 0-5-1.800-5.800-4.300H3.200v2.700a10.500 10.500 0 0 0 8.800 5.700z"/><path fill="#FBBC05" d="M6.200 14.100a6.300 6.300 0 0 1 0-4.100V7.300H3.200a10.500 10.500 0 0 0 0 9.400z"/><path fill="#EA4335" d="M12 5.700c1.500 0 2.900.5 4 1.600l3-3A10.500 10.500 0 0 0 3.200 7.300l3 2.700c.8-2.500 3.100-4.300 5.800-4.300z"/></svg>Continue with Google</button><div class="au-or"><span>or</span></div>
    <div class="au-f for-org"><label for="s-org">Organisation or brand name</label><input id="s-org" name="s-org" type="text" autocomplete="off"><p class="au-err" id="s-org-e" hidden></p></div>
    <div class="au-f"><label for="s-name">Full name</label><input id="s-name" name="s-name" type="text" autocomplete="off"><p class="au-err" id="s-name-e" hidden></p></div>
    <div class="au-f"><label for="s-email">Email address</label><input id="s-email" name="s-email" type="email" autocomplete="off"><p class="au-err" id="s-email-e" hidden></p></div>
    <div class="au-f"><label for="s-phone">Phone number</label><div class="au-tel"><span aria-hidden="true">+234</span><input id="s-phone" name="s-phone" type="tel" inputmode="tel" autocomplete="off" placeholder="801 234 5678" aria-label="Phone number, Nigeria code +234"></div><p class="au-err" id="s-phone-e" hidden></p></div>
    <div class="au-f"><div class="au-lab"><label for="s-pass">Password</label></div><div class="au-pw"><input id="s-pass" name="s-pass" type="password" autocomplete="off"><button type="button" class="au-eye" aria-pressed="false" aria-label="Show password">Show</button></div><div class="au-meter" aria-hidden="true"><i></i><i></i><i></i></div><p class="au-hint" id="pw-hint">Use at least 8 characters.</p><p class="au-err" id="s-pass-e" hidden></p></div>
    <button class="btn btn-hot au-go" type="submit"><span class="for-att">Create account</span><span class="for-org">Register and create your event</span></button><div class="au-done" role="status" hidden></div>
    <p class="au-legal">By creating an account, you agree to our <a href="/policies/terms">Terms</a> and confirm you've read our <a href="/policies/privacy">Privacy policy</a>. Organisers also agree to the <a href="/policies/organisers">Organiser terms</a>.</p>
    <p class="au-alt">Already have an account? <a href="/login">Log in</a></p>
  </form></div></div></section>
@endverbatim
